import { join } from "node:path";
import { migrate } from "drizzle-orm/better-sqlite3/migrator";
import type { Db } from "./client";

/** Folder holding the committed migrations generated by `drizzle-kit`. */
export const MIGRATIONS_FOLDER = join(process.cwd(), "drizzle");

/** Apply any pending migrations from `drizzle/` to `db`. Safe to run repeatedly. */
export function runMigrations(db: Db, migrationsFolder = MIGRATIONS_FOLDER): void {
  migrate(db, { migrationsFolder });
}
